class CircularBuffer:
    def __init__(self, size):
        self.size = size
        self.buffer = [None] * size
        self.head = 0
        self.tail = 0
        self.full = False

    def enqueue(self, item):
        if self.full:
            # If buffer is full, overwrite the oldest element
            self.buffer[self.head] = item
            self.head = (self.head + 1) % self.size
            self.tail = (self.tail + 1) % self.size
        else:
            # Add new item to the tail
            self.buffer[self.tail] = item
            self.tail = (self.tail + 1) % self.size
            # Check if buffer is now full
            if self.head == self.tail:
                self.full = True

    def dequeue(self):
        if self.head == self.tail and not self.full:
            raise IndexError("Buffer is empty")

        item = self.buffer[self.head]
        self.buffer[self.head] = None
        self.head = (self.head + 1) % self.size
        self.full = False
        return item

    def is_empty(self):
        return self.head == self.tail and not self.full

    def is_full(self):
        return self.full

    def __len__(self):
        if self.full:
            return self.size
        return (self.tail - self.head) % self.size

    def __str__(self):
        if self.is_empty():
            return "[]"
        result = []
        idx = self.head
        while idx != self.tail:
            result.append(str(self.buffer[idx]))
            idx = (idx + 1) % self.size
        return "[" + ", ".join(result) + "]"
